package agentdocs

import (
	"bytes"
	"io/fs"
	"sort"
)

// Stale returns, sorted, every path in generated whose file in tree is absent
// or differs from the generated bytes. A tool calls it from a test or a
// doctor row with what its generator would write now (a cobra/doc reference,
// say), so a committed copy that drifted from the binary is named. Files the
// tree holds beyond generated are not judged.
func Stale(tree fs.FS, generated map[string][]byte) []string {
	var stale []string
	for p, want := range generated {
		got, err := fs.ReadFile(tree, p)
		if err != nil || !bytes.Equal(got, want) {
			stale = append(stale, p)
		}
	}
	sort.Strings(stale)
	return stale
}
